import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Изображения — самая тяжёлая часть почти любого сайта. Одно необработанное фото может весить больше, чем вся остальная страница вместе взятая.</p>\n<p>Оптимизатор изображений для сайта решает эту проблему. Он сжимает изображения под конкретные места на странице, а затем выдаёт HTML для вставки прямо на страницу.</p>\n<p>Это руководство объясняет пресеты, настройки и порядок работы, чтобы сделать весь сайт быстрее. Начать можно прямо сейчас: инструмент <a href=\"/ru/optimizirovat-izobrazheniya-dlya-sajta/\">Оптимизатор изображений для сайта</a> сожмёт картинки под каждое место на странице и выдаст готовый HTML.</p>\n<h2 id=\"what-is-web-optimisation\">Что такое оптимизация изображений для сайта</h2>\n<p>Оптимизация для сайта — это подготовка изображения под конкретную задачу на странице. Главное изображение, фото товара и миниатюра нуждаются в разных размерах и форматах.</p>\n<p>Она охватывает четыре вещи: вес файла, размеры, формат и HTML. Когда все четыре правильные, изображение загружается быстро и выглядит резко.</p>\n<p>HTML решает, как браузер относится к изображению. Ленивая загрузка, ширина, высота и alt-текст живут в теге, и все они влияют на скорость и доступность.</p>\n<p>Оптимизация — это не только сжатие. Это подготовка изображения под его место на странице.</p>\n<h2 id=\"presets-explained\">Пресеты: объяснение</h2>\n<p>Инструмент предлагает пять пресетов, каждый под реальное место на сайте. Они задают размеры, формат и качество одним нажатием.</p>\n<p>«Товар для магазина» — пресет по умолчанию. Он ограничивает изображения шириной 1200 пикселей в WebP при качестве 82 процента, что идеально подходит для фото товаров.</p>\n<p>Другие пресеты охватывают главные изображения, карточки, миниатюры и изображения для соцсетей. Каждый соответствует месту, в честь которого назван.</p>\n<p>Пресеты — это начальные точки, а не тюрьма. После выбора пресета любую настройку можно изменить, комбинируя их под свою страницу.</p>\n<p>Начинайте с пресета, ближайшего к вашему месту. Настраивайте дальше, только если результат не подходит дизайну.</p>\n<h2 id=\"hero-images\">Главные изображения</h2>\n<p>Главные изображения заполняют верх страницы, поэтому они важнее всего для первого впечатления и для метрики Largest Contentful Paint.</p>\n<p>Главное изображение должно быть достаточно большим, чтобы выглядеть резко на широких экранах, но не больше. Слишком большое главное изображение тратит трафик на пиксели, которые никто не видит.</p>\n<p>Используйте WebP для главных изображений на современных сайтах. При том же качестве большое изображение в WebP легче, чем в JPG.</p>\n<p>Никогда не используйте ленивую загрузку для главного изображения. Оно находится выше сгиба, поэтому браузер должен загрузить его сразу, а не ждать прокрутки.</p>\n<p>Предзагружайте главное изображение, когда можете. Раннее сообщение браузеру о самом важном изображении реально сокращает время первой отрисовки.</p>\n<h2 id=\"product-images\">Фото товаров</h2>\n<p>Фото товаров продают товар, поэтому они должны оставаться резкими. Пресет «Товар для магазина» ограничивает их шириной 1200 пикселей, что подходит большинству макетов магазинов.</p>\n<p>Держите фон чистым, а товар — по центру. Аккуратный снимок сжимается лучше и выглядит профессиональнее.</p>\n<p>WebP идеален для фото товаров в современных магазинах. Для маркетплейсов, требующих JPG, переключите формат и сохраните те же размеры.</p>\n<p>Проверьте страницу товара на телефоне после загрузки. Большинство покупателей смотрят с мобильных устройств, и именно там изображение должно выглядеть хорошо.</p>\n<p>Сжимайте все фото каталога одним стандартом. Одинаковый вес и размеры делают каталог аккуратным и быстрым.</p>\n<h2 id=\"cards-thumbnails\">Карточки и миниатюры</h2>\n<p>Карточки и миниатюры показываются маленькими, поэтому им нужно меньше всего данных. Изображения шириной 400 пикселей вполне достаточно для карточки, показанной шириной 300 пикселей.</p>\n<p>Маленькие изображения терпят более сильное сжатие. Миниатюра при низком качестве всё равно выглядит чисто, потому что малый размер показа скрывает мягкость.</p>\n<p>Используйте ленивую загрузку для карточек ниже сгиба. Они не видны при открытии страницы, поэтому браузер может загрузить их позже.</p>\n<p>Держите соотношение сторон одинаковым для всех карточек. Сетка со смешанными пропорциями выглядит неряшливо и заставляет браузер перестраивать страницу.</p>\n<p>Миниатюры — это место, где оптимизация окупается больше всего. Страница с двадцатью карточками экономит мегабайты, когда каждая миниатюра правильно подобрана по размеру.</p>\n<h2 id=\"copy-img-button\">Кнопка «Копировать тег изображения»</h2>\n<p>Кнопка «Копировать тег изображения» записывает полный HTML для вашего оптимизированного изображения. Она включает источник, размеры, alt-текст и поведение загрузки.</p>\n<p>Вставьте скопированный HTML прямо на свою страницу. Не нужно писать тег вручную и гадать с атрибутами.</p>\n<p>Проверьте вставленный HTML перед публикацией. Убедитесь, что источник правильный и размеры соответствуют месту на странице.</p>\n<p>Если вы изменили изображение после копирования, скопируйте тег заново. Старый тег будет указывать на старую версию.</p>\n<p>Держите alt-текст описательным: он помогает поисковикам и программам чтения с экрана.</p>\n<h2 id=\"lazy-loading\">Ленивая загрузка</h2>\n<p>Ленивая загрузка откладывает изображения до тех пор, пока они не понадобятся. Это один из самых простых выигрышей в скорости на страницах с множеством изображений.</p>\n<p>Оптимизатор добавляет ленивую загрузку автоматически для подходящих пресетов. Пресет главного изображения оставляет её выключенной — и это правильно.</p>\n<p>Никогда не используйте ленивую загрузку для главного изображения или логотипа. Они видны сразу, и их задержка вредит первому впечатлению и метрике LCP.</p>\n<p>Ленивая загрузка включена для изображений ниже сгиба. Она говорит браузеру ждать, пока изображение не приблизится к области просмотра, прежде чем загружать его.</p>\n<p>Проверьте страницу после добавления ленивой загрузки. Прокрутите вниз и убедитесь, что изображения появляются плавно при входе в область просмотра.</p>\n<h2 id=\"formats-web\">Форматы для сайта</h2>\n<p>WebP — лучший выбор для современных сайтов: при том же качестве он легче JPG. Используйте его для главных изображений, товаров и карточек.</p>\n<p>JPG остаётся необходимым для совместимости. Почта, соцсети и старые системы по-прежнему предпочитают JPG, и пресет для соцсетей переключается на него автоматически.</p>\n<p>Генерируйте обе версии каждого изображения. Оптимизатор создаёт копию WebP, а копия JPG из того же пресета служит запасным вариантом.</p>\n<p>Проверяйте, что ваша платформа поддерживает WebP. Если нет, используйте JPG с теми же размерами и качеством.</p>\n<p>Формат — это не только вес, но и совместимость. Лучший формат — тот, который покажут все браузеры ваших посетителей.</p>\n<h2 id=\"quality-slider\">Ползунок качества</h2>\n<p>Большинство пресетов находятся в диапазоне от 75 до 85 процентов. Этот диапазон даёт чистые результаты при малом весе файла почти для любого изображения.</p>\n<p>Настраивайте ползунок, только когда результат пресета не подходит изображению. Детальное фото может захотеть 85, а простой графике хватит 70.</p>\n<p>Проверяйте результат в полном размере после каждого изменения. Маленькая миниатюра скрывает различия, которые видны в полном размере.</p>\n<p>Не гонитесь за максимальным качеством: разница между 85 и 95 процентами почти незаметна, а вес файла растёт сильно.</p>\n<p>Запишите качество, которое сработало для каждого типа изображений. В следующий раз настройка займёт секунды.</p>\n<h2 id=\"exif-stripping\">Удаление EXIF-данных</h2>\n<p>Фото содержат скрытые метаданные EXIF: модель камеры, настройки съёмки и иногда GPS-координаты. Оптимизатор удаляет их при сжатии.</p>\n<p>Для клиентских работ удаление обязательно. Неопубликованные продукты и частные места не должны просачиваться через метаданные изображения.</p>\n<p>Удаление метаданных также уменьшает вес файла. GPS-метки и миниатюры внутри EXIF весят килобайты, которые никому не нужны.</p>\n<p>Проверьте один файл после оптимизации на метаданные. Убедитесь, что GPS-метки действительно удалены.</p>\n<p>Если метаданные нужны — например, для фотопортфолио с данными о камере — сохраните копию оригинала отдельно.</p>\n<h2 id=\"batch-web\">Пакетный режим для сайта</h2>\n<p>Можно оптимизировать много изображений одной партией. Перетащите тридцать изображений блога, выберите пресет и скачайте их все вместе.</p>\n<p>Держите пресет одинаковым для всей партии. Смешанные настройки дают смешанные результаты, которые на живом сайте выглядят неряшливо.</p>\n<p>Проверьте несколько результатов перед скачиванием всего архива. Если одно изображение выглядит мягким, измените его настройки и запустите только его заново.</p>\n<p>Для точных целей по весу вместо пресетов используйте <a href=\"/ru/szhat-izobrazhenie-do-tselego-razmera/\">компрессор до точного размера файла</a>: он принимает любое введённое число.</p>\n<p>Называйте файлы понятно после распаковки. Архив с общими именами создаёт путаницу при загрузке на сайт.</p>\n<h2 id=\"og-images\">Изображения для соцсетей (Open Graph)</h2>\n<p>Изображения Open Graph нуждаются в конкретных размерах, обычно 1200 на 630 пикселей. Пресет для соцсетей подбирает размеры правильно и переключается на JPG.</p>\n<p>Держите файл меньше нескольких сотен килобайт. Тяжёлое изображение для предпросмотра медленно загружается в карточке, а некоторые платформы вообще его пропускают.</p>\n<p>Проверьте карточку для соцсетей перед публикацией. У каждой крупной платформы есть отладчик, который показывает, как будет выглядеть предпросмотр.</p>\n<p>Используйте чёткое изображение с крупным текстом. Маленький текст на карточке не читается, когда её показывают в ленте.</p>\n<p>Обновляйте изображение Open Graph вместе со статьёй. Устаревшая карточка вводит читателей в заблуждение.</p>\n<h2 id=\"retina-web\">Экраны Retina и сайт</h2>\n<p>Решение — подавать изображение вдвое шире его размера показа. Миниатюра, показанная шириной 400 пикселей, должна быть шириной 800 пикселей в файле.</p>\n<p>Пресеты оптимизатора учитывают это. Пресет карточки создаёт изображение, которое остаётся резким на экранах с высоким DPI, не тратя трафик впустую.</p>\n<p>Для маленьких миниатюр это мало значит. Для больших главных изображений разница между обычным файлом и файлом, готовым для Retina, видна.</p>\n<p>Проверяйте на настоящем экране с высоким DPI, когда можете. Скриншоты результата скрывают именно ту мягкость, которую вы пытаетесь проверить.</p>\n<p>Не подавайте изображения вчетверо шире показа: лишний вес не окупается видимым улучшением.</p>\n<h2 id=\"alt-text-web\">Alt-текст для сайта</h2>\n<p>Каждое изображение на сайте нуждается в описательном alt-тексте. Поисковики не видят картинку, они читают её описание.</p>\n<p>Пишите alt-текст коротко и по делу: что на изображении и зачем оно здесь. Избегайте набивки ключевыми словами.</p>\n<p>Хороший alt-текст помогает и людям: программы чтения с экрана озвучивают его пользователям с нарушениями зрения.</p>\n<p>Оптимизатор включает alt-текст в скопированный HTML. Заполните его до копирования, чтобы не править тег вручную.</p>\n<p>Для декоративных изображений используйте пустой alt-текст. Программы чтения пропустят их, а не будут озвучивать мусор.</p>\n<h2 id=\"cdn-caching\">CDN и кэширование</h2>\n<p>Задавайте долгое время кэширования для изображений, которые редко меняются. Логотип или фото товара могут безопасно кэшироваться месяцами.</p>\n<p>Когда изображение меняется, меняйте и его имя файла. Так браузер не покажет старую закэшированную версию вместо новой.</p>\n<p>Используйте CDN для изображений, если ваша платформа это поддерживает. CDN подаёт изображения с сервера ближе к посетителю.</p>\n<p>Оптимизированные изображения и CDN работают вместе: лёгкий файл с близкого сервера загружается быстрее всего.</p>\n<p>Проверяйте кэширование после публикации. Инструменты разработчика покажут, загружается ли изображение из кэша или заново.</p>\n<h2 id=\"webp-fallback\">Запасной вариант для WebP</h2>\n<p>Не все браузеры и системы поддерживают WebP. Запасной вариант JPG гарантирует, что изображение покажется везде.</p>\n<p>Генерируйте обе версии каждого изображения. Оптимизатор создаёт копию WebP, а копия JPG из того же пресета служит запасным вариантом.</p>\n<p>В HTML запасной вариант реализуется через элемент picture: браузер выбирает WebP, если поддерживает его, и JPG — если нет.</p>\n<p>Проверьте запасной вариант в старом браузере. Убедитесь, что изображение действительно показывается, а не исчезает.</p>\n<p>Когда WebP станет повсеместным, запасной вариант можно будет убрать. Пока что держите обе версии.</p>\n<h2 id=\"measuring-web\">Измерение результатов</h2>\n<p>Проверьте Core Web Vitals после оптимизации. LCP должен улучшиться больше всего, потому что главное изображение обычно — самая большая отрисовка.</p>\n<p>Измерьте скорость страницы до и после замены изображений. Инструменты вроде PageSpeed Insights покажут реальную разницу.</p>\n<p>Проверьте вес страницы на мобильном соединении. Именно там лёгкие изображения дают самый заметный выигрыш.</p>\n<p>Следите за отказами и жалобами. Если изображения перестали медленно грузиться, оптимизация работает.</p>\n<p>Ведите простую запись: вес страницы до и после, время загрузки, оценка PageSpeed. Числа убеждают коллег лучше любых аргументов.</p>\n<p>Когда запускаете новый сайт, начните с главных изображений: они влияют на скорость и первое впечатление сильнее всего. Остальные оптимизируйте следом.</p>\n<p>Составьте карту изображений сайта: какое изображение где показывается и какого оно размера. Карта показывает, где прячутся самые тяжёлые файлы.</p>\n<p>Проверяйте скорость после каждой большой публикации. Новые изображения и плагины постепенно замедляют сайт, и регулярные проверки ловят проблему рано.</p>\n<p>Обучите коллег, которые загружают изображения. Общая заметка с пресетами экономит часы объяснений и делает сайт предсказуемо быстрым.</p>\n<p>Не забывайте про alt-текст: он помогает не только поисковикам, но и читателям с нарушениями зрения. Пишите его коротко и по делу.</p>\n<p>Когда платформа меняет требования к изображениям, обновляйте пресеты. Прошлогодние настройки могут не подойти под новую вёрстку.</p>\n<p>Тестируйте новые форматы на своих изображениях. WebP сегодня даёт выигрыш, а завтра его может дать следующий формат.</p>\n<p>Измеряйте результаты и записывайте их: вес страницы до и после, оценка PageSpeed, время загрузки. Числа убеждают коллег лучше любых аргументов.</p>\n<p>И помните: оптимизация — это не разовая задача, а привычка. Каждое новое изображение должно проходить через оптимизатор.</p>\n<p>Изображения Open Graph нуждаются в конкретных размерах, обычно 1200 на 630 пикселей. Пресет для соцсетей подбирает размеры правильно и переключается на JPG.</p>\n<p>Решение для экранов Retina — подавать изображение вдвое шире его размера показа. Миниатюра, показанная шириной 400 пикселей, должна быть шириной 800 пикселей в файле.</p>\n<p>Каждое изображение на сайте нуждается в описательном alt-тексте. Поисковики не видят картинку, они читают её описание.</p>\n<p>Задавайте долгое время кэширования для изображений, которые редко меняются. Логотип или фото товара могут безопасно кэшироваться месяцами.</p>\n<p>Не все браузеры поддерживают WebP, поэтому генерируйте обе версии каждого изображения: WebP для современных браузеров и JPG как запасной вариант.</p>\n<p>Проверьте Core Web Vitals после оптимизации. LCP должен улучшиться больше всего, потому что главное изображение обычно — самая большая отрисовка.</p>\n<p>Можно оптимизировать много изображений одной партией: перетащите тридцать изображений блога, выберите пресет и скачайте их все вместе.</p>\n<p>Чек-лист перед публикацией изображений: пресет подходит месту на странице, ленивая загрузка выключена для главного изображения, alt-текст заполнен, размеры указаны в HTML.</p>\n<p>Если изображение меняется, меняйте и его имя файла. Так браузер не покажет старую закэшированную версию вместо новой.</p>\n<p>Для логотипа используйте SVG, а не растровый формат: он резкий при любом размере и весит мало. Растровые форматы нужны для фото, а не для логотипов.</p>\n<p>Практические шаги читайте в статье <a href=\"/ru/blog/kak-optimizirovat-izobrazheniya-dlya-skorosti-sayta/\">Как оптимизировать изображения для скорости сайта</a>. Про Core Web Vitals — в статье <a href=\"/ru/blog/optimizatsiya-izobrazheniy-core-web-vitals-lcp/\">Оптимизация изображений для Core Web Vitals: LCP и размер файла</a>. Для точных лимитов используйте <a href=\"/ru/szhat-izobrazhenie-do-200-kb/\">компрессор до 200 КБ</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Какой пресет выбрать для главного изображения?","answer":"Пресет главного изображения: он подбирает размеры для широких экранов, использует WebP и выключает ленивую загрузку. Главное изображение находится выше сгиба, поэтому браузер должен загрузить его сразу. Предзагрузите его, когда можете."},{"question":"Почему инструмент переключается на JPG для изображений для соцсетей?","answer":"Потому что соцсети и почтовые клиенты до сих пор предпочитают JPG, а некоторые плохо обрабатывают WebP. Пресет для соцсетей переключается на JPG автоматически, чтобы карточка предпросмотра показывалась везде. Размеры при этом остаются правильными — 1200 на 630 пикселей."},{"question":"Стоит ли включать ленивую загрузку для главного изображения?","answer":"Нет. Главное изображение видно сразу при открытии страницы, и его задержка вредит первому впечатлению и метрике LCP. Ленивая загрузка нужна только изображениям ниже сгиба — карточкам, миниатюрам и галереям."},{"question":"Что делает опция «Только уменьшение»?","answer":"Она запрещает увеличивать маленькие изображения до размеров пресета. Если исходник меньше целевого размера, инструмент оставит его как есть, а не растянет. Растягивание маленького изображения только размывает его без пользы."},{"question":"Почему скачанные файлы называются с суффиксом -web в конце?","answer":"Чтобы отличить оптимизированные копии для сайта от оригиналов. Суффикс -web сразу говорит, что файл подготовлен для страницы: сжат, обрезан под место и готов к загрузке. Оригиналы при этом остаются нетронутыми."},{"question":"Можно ли использовать оптимизатор изображений для сайта вместо пакетного компрессора?","answer":"Для сайта — да, и это лучший выбор: пресеты под места на странице и готовый HTML экономят время. Пакетный компрессор лучше подходит, когда нужны просто меньшие файлы без привязки к местам на странице. Для точных лимитов в килобайтах используйте инструменты с точным размером."}];
